const result = $input.first().json;
if (result.status !== 'succeeded') throw new Error('BeatAPI Social Data search did not succeed.');
const edges = result.data?.data?.hashtag?.edge_hashtag_to_media?.edges;
const items = Array.isArray(edges) ? edges : (Array.isArray(result.items) ? result.items : null);
if (!items) throw new Error('No hashtag posts array was returned. Inspect the Social Data response and action availability.');
const records = items.slice(0, 12).map((entry) => {
const p = entry.node ?? entry;
const id = String(p.id ?? p.media_id ?? p.pk ?? p.shortcode ?? p.code ?? '');
const shortcode = String(p.shortcode ?? p.code ?? '');
const url = p.url ?? p.permalink ?? (shortcode ? 'https://www.instagram.com/p/' + shortcode + '/' : '');
const captionEdges = p.edge_media_to_caption?.edges;
const captionText = Array.isArray(captionEdges) ? captionEdges.map((e) => e.node?.text ?? '').filter(Boolean).join(' ') : '';
const caption = String(captionText || p.caption?.text || p.caption || p.text || p.description || '').slice(0, 1400);
return { id, url, author: p.username ?? p.user?.username ?? p.owner?.username ?? '', caption, likes: p.edge_liked_by?.count ?? p.like_count ?? p.likes ?? null, comments: p.edge_media_to_comment?.count ?? p.comment_count ?? p.comments_count ?? null, created_at: p.taken_at_timestamp ?? p.taken_at ?? p.created_at ?? null };
}).filter((p) => (p.id || p.url) && p.caption);
if (!records.length) throw new Error('No identifiable public hashtag posts were found. Try another hashtag or inspect the response.');
return [{ json: { source: 'Instagram public hashtag posts', source_count: records.length, items_total: items.length, preview_truncated: items.length > records.length, request_ids: result.request_id ? [result.request_id] : [], prompt: JSON.stringify({ keyword: $('Configure Inputs').first().json.keyword, records }) } }];

const answer = $input.first().json.choices?.[0]?.message?.content;
if (!answer) throw new Error('The text model returned no message content.');
const evidence = $('Prepare Evidence').first().json;
return [{ json: { summary: answer, source: evidence.source, source_count: evidence.source_count, items_total: evidence.items_total, preview_truncated: evidence.preview_truncated, request_ids: evidence.request_ids } }];
